from bisect import bisect_left

def maxNested(envelopes):
    envs = sorted(envelopes, key=lambda e: (e[0], -e[1]))
    tails = []
    for _, h in envs:
        k = bisect_left(tails, h)
        if k == len(tails):
            tails.append(h)
        else:
            tails[k] = h
    return len(tails)
